#include <iostream>
#include <limits>

int main() {
    using namespace std;

    // Check the rounding style for double
    auto style = numeric_limits<double>::round_style;

    cout << "Double rounding style: ";

    if (style == round_to_nearest) {
        cout << "Round to nearest (IEEE standard)" << endl;
    } else if (style == round_toward_zero) {
        cout << "Round toward zero (Truncation)" << endl;
    } else {
        cout << "Other or Indeterminate style: " << style << endl;
    }
}
